import unittest

from solution import axis_sums


class AxisSumsTests(unittest.TestCase):
    def setUp(self):
        self.cube = [
            [[1, 2, 3], [4, 5, 6]],
            [[10, 20, 30], [40, 50, 60]],
        ]

    def test_sum_over_axis_zero(self):
        self.assertEqual(axis_sums(self.cube, 0), [[11, 22, 33], [44, 55, 66]])

    def test_sum_over_axis_one(self):
        self.assertEqual(axis_sums(self.cube, 1), [[5, 7, 9], [50, 70, 90]])

    def test_sum_over_axis_two(self):
        self.assertEqual(axis_sums(self.cube, 2), [[6, 15], [60, 150]])

    def test_singleton_dimensions(self):
        cube = [[[2.5]]]
        self.assertEqual(axis_sums(cube, 0), [[2.5]])
        self.assertEqual(axis_sums(cube, 1), [[2.5]])
        self.assertEqual(axis_sums(cube, 2), [[2.5]])

    def test_iterables_are_supported_and_input_is_not_mutated(self):
        cube = [[[1, 2], [3, 4]]]
        original = [[[1, 2], [3, 4]]]
        result = axis_sums(cube, 2)
        self.assertEqual(result, [[3, 7]])
        result[0][0] = 999
        self.assertEqual(cube, original)

        generated = ((tuple(line) for line in plane) for plane in self.cube)
        self.assertEqual(axis_sums(generated, 0), [[11, 22, 33], [44, 55, 66]])

    def test_axis_validation(self):
        for axis in [True, False, 1.0, "1", None]:
            with self.subTest(axis=axis):
                with self.assertRaises(TypeError):
                    axis_sums(self.cube, axis)
        for axis in [-1, 3]:
            with self.subTest(axis=axis):
                with self.assertRaises(ValueError):
                    axis_sums(self.cube, axis)

    def test_rejects_empty_and_ragged_dimensions(self):
        invalid = [
            [], [[]], [[[]]],
            [[[1]], [[2], [3]]],
            [[[1, 2], [3]]],
            [[[1]], [[2, 3]]],
        ]
        for cube in invalid:
            with self.subTest(cube=cube):
                with self.assertRaises((TypeError, ValueError)):
                    axis_sums(cube, 0)

    def test_rejects_malformed_and_nonfinite_values(self):
        invalid = [
            "cube", b"cube", None,
            [[[True]]], [[["1"]]], [[[None]]],
            [[[float("inf")]]], [[[float("-inf")]]], [[[float("nan")]]],
        ]
        for cube in invalid:
            with self.subTest(cube=cube):
                with self.assertRaises((TypeError, ValueError)):
                    axis_sums(cube, 0)


if __name__ == "__main__":
    unittest.main()

